protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour set and graph cannot be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.<E>emptyList(), 0.0);
    }

    List<E> pathEdges = new ArrayList<>(tour);
    List<V> pathVertices = new ArrayList<>();

    V startVertex = null;
    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (startVertex == null) {
            startVertex = source;
            pathVertices.add(startVertex);
        }

        if (!pathVertices.contains(target)) {
            pathVertices.add(target);
        } else if (!pathVertices.contains(source)) {
            pathVertices.add(source);
        } else {
            throw new IllegalArgumentException("The provided set of edges does not form a valid path");
        }
    }

    if (!isClosedTour(pathEdges, startVertex, graph)) {
        throw new IllegalArgumentException("The provided set of edges does not form a closed tour");
    }

    return new GraphPathImpl<>(graph, startVertex, pathEdges, calculatePathWeight(pathEdges, graph));
}

private boolean isClosedTour(List<E> edges, V startVertex, Graph<V,E> graph) {
    V lastVertex = startVertex;
    for (E edge : edges) {
        if (graph.getEdgeSource(edge) == lastVertex) {
            lastVertex = graph.getEdgeTarget(edge);
        } else if (graph.getEdgeTarget(edge) == lastVertex) {
            lastVertex = graph.getEdgeSource(edge);
        } else {
            return false;
        }
    }
    return lastVertex.equals(startVertex);
}

private double calculatePathWeight(List<E> edges, Graph<V,E> graph) {
    double weight = 0.0;
    for (E edge : edges) {
        weight += graph.getEdgeWeight(edge);
    }
    return weight;
}

